const STORAGE_KEY_THEME = "cpp_handbook_theme_v2";
const STORAGE_KEY_LAST_MODULE = "cpp_handbook_last_module_v2";
const STORAGE_KEY_VIEW_MODE = "cpp_handbook_view_mode_v1";
const STORAGE_KEY_SPLIT = "cpp_handbook_split_pct_v1";

const MOBILE_QUERY = window.matchMedia("(max-width: 900px)");

// All content is static JSON (generated by serve.py locally, or by
// `serve.py --build` for GitHub Pages). Paths are relative so the site
// also works under a sub-path like /<repo>/.
const DATA_URL = {
  curriculum: "data/curriculum.json",
  module: (id) => `data/modules/${encodeURIComponent(id)}.json`,
  searchIndex: "data/search-index.json",
};
const SEARCH_LIMIT = 35;

let curriculumData = null;
let flatModules = [];
let currentModule = null;
let activeFileIndex = 0;
let selectToken = 0;
let isFirstLoad = true;
let preferredMode = safeGet(STORAGE_KEY_VIEW_MODE) || "split"; // desktop / tablet landscape
let compactMode = "theory"; // phones & tablet portrait: one pane at a time, not persisted

// ==================== HELPERS ====================
function safeGet(key) {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeSet(key, val) {
  try {
    localStorage.setItem(key, val);
  } catch {
    /* storage unavailable */
  }
}

function escapeHtml(str) {
  return String(str ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function cleanTitle(title) {
  return stripTicks(title).replace(/^Bài\s+[\d.]+:\s*/i, "");
}

function stripTicks(title) {
  return String(title || "").replace(/`/g, "");
}

async function copyText(text, btn, idleLabel) {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    ta.remove();
  }
  btn.textContent = "Copied";
  btn.classList.add("flash");
  setTimeout(() => {
    btn.textContent = idleLabel;
    btn.classList.remove("flash");
  }, 1200);
}

// DOM Elements
const sidebarEl = document.getElementById("sidebar");
const sidebarBackdropEl = document.getElementById("sidebar-backdrop");
const curriculumNavEl = document.getElementById("curriculum-nav");
const statsSummaryEl = document.getElementById("stats-summary");
const searchInputEl = document.getElementById("search-input");
const searchKbdEl = document.getElementById("search-kbd");
const searchClearBtn = document.getElementById("search-clear");
const searchResultsPanelEl = document.getElementById("search-results-panel");

const readmePathLabelEl = document.getElementById("readme-path-label");
const docQuickFilesEl = document.getElementById("doc-quick-files");
const docScrollEl = document.getElementById("doc-scroll");
const markdownContainerEl = document.getElementById("markdown-container");
const workspaceEl = document.getElementById("workspace");
const theoryPaneEl = document.getElementById("theory-pane");

const prevBtn = document.getElementById("prev-module-btn");
const nextBtn = document.getElementById("next-module-btn");
const prevPagerTitleEl = document.getElementById("prev-pager-title");
const nextPagerTitleEl = document.getElementById("next-pager-title");

const fileTabsBarEl = document.getElementById("file-tabs-bar");
const activeFileLangEl = document.getElementById("active-file-lang");
const activeFileNameEl = document.getElementById("active-file-name");
const activeFileLinesEl = document.getElementById("active-file-lines");
const lineGutterEl = document.getElementById("line-gutter");
const codeHighlightBlockEl = document.getElementById("code-highlight-block");
const editorViewportEl = document.getElementById("editor-viewport");
const copyCodeBtn = document.getElementById("copy-code-btn");
const downloadCodeBtn = document.getElementById("download-code-btn");

// ==================== THEME ====================
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  safeSet(STORAGE_KEY_THEME, theme);
  document.getElementById("theme-icon-dark").classList.toggle("hidden", theme !== "dark");
  document.getElementById("theme-icon-light").classList.toggle("hidden", theme === "dark");
}

function initTheme() {
  const saved =
    safeGet(STORAGE_KEY_THEME) ||
    (window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
  applyTheme(saved);
}

document.getElementById("theme-toggle-btn").addEventListener("click", () => {
  const cur = document.documentElement.getAttribute("data-theme");
  applyTheme(cur === "dark" ? "light" : "dark");
});

// ==================== CURRICULUM LOADING ====================
async function loadCurriculum() {
  try {
    const res = await fetch(DATA_URL.curriculum);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    curriculumData = await res.json();
  } catch (err) {
    statsSummaryEl.textContent = "Không tải được dữ liệu";
    markdownContainerEl.innerHTML = `<div class="state-msg err">Không tải được lộ trình học (${escapeHtml(
      err.message
    )}). Nếu đang mở file trực tiếp, hãy chạy <code>python3 serve.py</code> rồi mở lại trang.</div>`;
    return;
  }

  statsSummaryEl.textContent = `${curriculumData.totalModules} bài · ${curriculumData.totalCodeFiles} file mã nguồn`;

  flatModules = [];
  curriculumData.stages.forEach((st) => {
    st.modules.forEach((m) => {
      flatModules.push({ ...m, stageCode: st.stageCode, stageTitle: st.stageTitle });
    });
  });

  renderSidebar();

  const hashId = decodeURIComponent(window.location.hash.replace("#", ""));
  const lastId = safeGet(STORAGE_KEY_LAST_MODULE);
  const exists = (id) => id && flatModules.some((m) => m.id === id);
  const initialId = exists(hashId) ? hashId : exists(lastId) ? lastId : "ROOT";
  await selectModule(initialId);
}

function makeNavItem(mod) {
  const item = document.createElement("button");
  item.className = `nav-item ${mod.isMiniProject ? "is-project" : ""}`;
  item.dataset.moduleId = mod.id;
  item.title = stripTicks(mod.title);
  item.innerHTML = `
    <span class="nav-code">${escapeHtml(mod.code)}</span>
    <span class="nav-label">${escapeHtml(cleanTitle(mod.title))}</span>
  `;
  item.addEventListener("click", () => {
    selectModule(mod.id);
    if (MOBILE_QUERY.matches) closeSidebar();
  });
  return item;
}

function renderSidebar() {
  curriculumNavEl.innerHTML = "";
  const chevron = `
    <svg class="stage-chevron" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
      <polyline points="6 9 12 15 18 9"></polyline>
    </svg>`;

  curriculumData.stages.forEach((st) => {
    // Overview stage holds only the roadmap: show it as one top-level row
    if (st.modules.length === 1 && st.modules[0].id === "ROOT") {
      const wrap = document.createElement("div");
      wrap.className = "nav-overview";
      const item = document.createElement("button");
      item.className = "nav-item nav-root";
      item.dataset.moduleId = "ROOT";
      item.innerHTML = `<span class="stage-badge">${escapeHtml(st.stageCode)}</span><span class="nav-label">${escapeHtml(
        st.stageTitle
      )}</span>`;
      item.addEventListener("click", () => {
        selectModule("ROOT");
        if (MOBILE_QUERY.matches) closeSidebar();
      });
      wrap.appendChild(item);
      curriculumNavEl.appendChild(wrap);
      return;
    }

    const lessons = st.modules.filter((m) => !m.isMiniProject).length;
    const projects = st.modules.length - lessons;
    const metaText = `${lessons} bài${projects ? ` · ${projects} mini-project` : ""}`;

    const block = document.createElement("div");
    block.className = "stage-block collapsed";
    block.dataset.stageId = st.stageId;

    const heading = document.createElement("button");
    heading.className = "stage-heading";
    heading.setAttribute("aria-expanded", "false");
    heading.innerHTML = `
      <span class="stage-badge">${escapeHtml(st.stageCode)}</span>
      <span class="stage-info">
        <span class="stage-title">${escapeHtml(st.stageTitle)}</span>
        <span class="stage-meta">${metaText}</span>
      </span>
      ${chevron}
    `;
    heading.addEventListener("click", () => {
      const collapsed = block.classList.toggle("collapsed");
      heading.setAttribute("aria-expanded", String(!collapsed));
    });

    const list = document.createElement("div");
    list.className = "stage-list";
    st.modules.forEach((mod) => list.appendChild(makeNavItem(mod)));

    block.appendChild(heading);
    block.appendChild(list);
    curriculumNavEl.appendChild(block);
  });
}

function highlightActiveNav() {
  let activeEl = null;
  document.querySelectorAll(".nav-item").forEach((el) => {
    const on = el.dataset.moduleId === currentModule.id;
    el.classList.toggle("active", on);
    if (on) activeEl = el;
  });
  document.querySelectorAll(".stage-block").forEach((b) => b.classList.remove("has-active"));
  const block = activeEl?.closest(".stage-block");
  if (block) {
    block.classList.add("has-active");
    block.classList.remove("collapsed");
    block.querySelector(".stage-heading").setAttribute("aria-expanded", "true");
  }
  activeEl?.scrollIntoView({ block: "nearest" });
}

// ==================== MODULE SELECTION ====================
async function selectModule(moduleId, targetFileName = null) {
  const token = ++selectToken;
  if (!flatModules.some((m) => m.id === moduleId)) moduleId = "ROOT"; // unknown hash
  let data;
  try {
    const res = await fetch(DATA_URL.module(moduleId));
    if (!res.ok) {
      if (moduleId !== "ROOT") return selectModule("ROOT");
      return;
    }
    data = await res.json();
  } catch (err) {
    if (token !== selectToken) return;
    markdownContainerEl.innerHTML = `<div class="state-msg err">Lỗi mạng: ${escapeHtml(err.message)}</div>`;
    return;
  }
  if (token !== selectToken) return; // a newer navigation won

  currentModule = data;

  if (decodeURIComponent(window.location.hash.replace("#", "")) !== currentModule.id) {
    const url = `#${encodeURIComponent(currentModule.id)}`;
    if (isFirstLoad) history.replaceState(null, "", url);
    else history.pushState(null, "", url);
  }
  isFirstLoad = false;
  safeSet(STORAGE_KEY_LAST_MODULE, currentModule.id);
  highlightActiveNav();

  const idx = flatModules.findIndex((m) => m.id === currentModule.id);

  document.title = `${cleanTitle(currentModule.title)} · C/C++ Handbook`;
  readmePathLabelEl.textContent = currentModule.id === "ROOT" ? "README.md" : `${currentModule.id}/README.md`;

  const prevMod = idx > 0 ? flatModules[idx - 1] : null;
  const nextMod = idx !== -1 && idx + 1 < flatModules.length ? flatModules[idx + 1] : null;
  prevPagerTitleEl.textContent = prevMod ? cleanTitle(prevMod.title) : "—";
  nextPagerTitleEl.textContent = nextMod ? cleanTitle(nextMod.title) : "—";
  prevBtn.disabled = !prevMod;
  nextBtn.disabled = !nextMod;

  renderQuickFilePills();
  renderMarkdown(currentModule.readme);

  const hasFiles = currentModule.files && currentModule.files.length > 0;
  document.querySelectorAll(".seg-btn").forEach((btn) => {
    btn.disabled = !hasFiles && btn.dataset.mode !== "theory";
  });

  if (!hasFiles) {
    fileTabsBarEl.innerHTML = "";
    applyViewMode("theory");
    return;
  }

  // on small screens each lesson opens on the theory, unless a code file was asked for
  compactMode = targetFileName ? "code" : "theory";
  applyViewMode(currentMode());
  let fIdx = 0;
  if (targetFileName) {
    const found = currentModule.files.findIndex((f) => f.name === targetFileName);
    if (found !== -1) fIdx = found;
  }
  renderFileTabs(fIdx);
}

function openFile(idx) {
  if (MOBILE_QUERY.matches) setViewMode("code");
  else if (workspaceEl.classList.contains("mode-theory")) setViewMode("split");
  selectFileTab(idx);
}

function renderQuickFilePills() {
  docQuickFilesEl.innerHTML = "";
  if (!currentModule.files || currentModule.files.length === 0) return;

  currentModule.files.forEach((f, idx) => {
    const pill = document.createElement("button");
    pill.className = "quick-file-pill";
    pill.textContent = f.name;
    pill.title = `Xem ${f.name}`;
    pill.addEventListener("click", () => openFile(idx));
    docQuickFilesEl.appendChild(pill);
  });
}

// ==================== MARKDOWN + MATH ====================
// Pull math out before marked runs so "_", "\\", "*" inside formulas aren't
// mangled into emphasis/escapes. Code fences and inline code are left alone.
function extractMath(md) {
  const store = [];
  const parts = md.split(/(```[\s\S]*?```|~~~[\s\S]*?~~~|`[^`\n]*`)/g);
  const out = parts
    .map((part, i) => {
      if (i % 2 === 1) return part; // code segment
      return part
        .replace(/\$\$([\s\S]+?)\$\$/g, (_, tex) => {
          store.push({ tex, display: true });
          return `@@MATH${store.length - 1}@@`;
        })
        .replace(/\$([^\$\n]+?)\$/g, (_, tex) => {
          store.push({ tex, display: false });
          return `@@MATH${store.length - 1}@@`;
        });
    })
    .join("");
  return { md: out, store };
}

function restoreMath(html, store) {
  return html.replace(/@@MATH(\d+)@@/g, (_, n) => {
    const item = store[Number(n)];
    if (!item) return "";
    if (window.katex) {
      try {
        return window.katex.renderToString(item.tex, {
          displayMode: item.display,
          throwOnError: false,
        });
      } catch {
        /* fall through */
      }
    }
    return `<code>${escapeHtml(item.tex)}</code>`;
  });
}

function renderMarkdown(mdText) {
  const { md, store } = extractMath(mdText || "");
  markdownContainerEl.innerHTML = restoreMath(marked.parse(md), store);
  docScrollEl.scrollTop = 0;

  markdownContainerEl.querySelectorAll("table").forEach((table) => {
    const wrap = document.createElement("div");
    wrap.className = "table-wrap";
    table.parentNode.insertBefore(wrap, table);
    wrap.appendChild(table);
  });

  markdownContainerEl.querySelectorAll("a[href^='http']").forEach((a) => {
    a.target = "_blank";
    a.rel = "noopener noreferrer";
  });

  markdownContainerEl.querySelectorAll("pre").forEach((preEl) => {
    const codeBlock = preEl.querySelector("code");
    if (codeBlock) {
      // unlabeled / ```text blocks still get the code theme, just no tokens
      if (!/\blanguage-/.test(codeBlock.className)) codeBlock.classList.add("language-none");
      Prism.highlightElement(codeBlock);
    }

    const wrapper = document.createElement("div");
    wrapper.className = "pre-wrapper";
    preEl.parentNode.insertBefore(wrapper, preEl);
    wrapper.appendChild(preEl);

    const copyBtn = document.createElement("button");
    copyBtn.className = "pre-copy-btn";
    copyBtn.textContent = "Copy";
    copyBtn.addEventListener("click", () => copyText(preEl.textContent, copyBtn, "Copy"));
    wrapper.appendChild(copyBtn);
  });

  // Make inline <code> references to lesson files clickable
  if (currentModule && currentModule.files) {
    const fileMap = new Map(currentModule.files.map((f, i) => [f.name, i]));
    markdownContainerEl.querySelectorAll(":not(pre) > code").forEach((codeEl) => {
      const txt = codeEl.textContent.trim();
      if (fileMap.has(txt)) {
        codeEl.classList.add("clickable-file-ref");
        codeEl.title = `Xem ${txt}`;
        codeEl.addEventListener("click", () => openFile(fileMap.get(txt)));
      }
    });
  }
}

// ==================== CODE VIEWER ====================
function updateLineGutter(codeStr) {
  const count = Math.max(1, codeStr.split("\n").length);
  let s = "1";
  for (let i = 2; i <= count; i++) s += "\n" + i;
  lineGutterEl.textContent = s;
}

function renderFileTabs(selectIdx = 0) {
  fileTabsBarEl.innerHTML = "";
  currentModule.files.forEach((f, idx) => {
    const tab = document.createElement("button");
    tab.className = "file-tab";
    tab.textContent = f.name;
    tab.addEventListener("click", () => selectFileTab(idx));
    fileTabsBarEl.appendChild(tab);
  });
  selectFileTab(selectIdx);
}

function selectFileTab(idx) {
  if (!currentModule || !currentModule.files[idx]) return;
  activeFileIndex = idx;
  const fileObj = currentModule.files[idx];

  fileTabsBarEl.querySelectorAll(".file-tab").forEach((tab, i) => {
    tab.classList.toggle("active", i === idx);
    if (i === idx) tab.scrollIntoView({ block: "nearest", inline: "nearest" });
  });

  const isCpp20 = currentModule.id === "32_Modern_CPP20_Features";
  activeFileLangEl.textContent = fileObj.lang === "c" ? "C11" : isCpp20 ? "C++20" : "C++17";
  activeFileNameEl.textContent = fileObj.name;
  activeFileLinesEl.textContent = `${fileObj.lines} dòng`;

  codeHighlightBlockEl.className = `language-${fileObj.lang}`;
  codeHighlightBlockEl.textContent = fileObj.content;
  Prism.highlightElement(codeHighlightBlockEl);
  updateLineGutter(fileObj.content);
  editorViewportEl.scrollTop = 0;
}

function downloadActiveFile() {
  const fileObj = currentModule?.files?.[activeFileIndex];
  if (!fileObj) return;
  const url = URL.createObjectURL(new Blob([fileObj.content], { type: "text/plain;charset=utf-8" }));
  const a = document.createElement("a");
  a.href = url;
  a.download = fileObj.name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

// ==================== DRAGGABLE SPLIT RESIZER ====================
const resizerV = document.getElementById("resizer-v");
let isDragging = false;

const savedSplit = parseFloat(safeGet(STORAGE_KEY_SPLIT));
if (savedSplit >= 25 && savedSplit <= 75) theoryPaneEl.style.width = `${savedSplit}%`;

resizerV.addEventListener("pointerdown", (e) => {
  e.preventDefault();
  isDragging = true;
  resizerV.classList.add("dragging");
  document.body.style.cursor = "col-resize";
  document.body.style.userSelect = "none";
});

window.addEventListener("pointermove", (e) => {
  if (!isDragging) return;
  const rect = workspaceEl.getBoundingClientRect();
  const pct = Math.min(75, Math.max(25, ((e.clientX - rect.left) / rect.width) * 100));
  theoryPaneEl.style.width = `${pct}%`;
});

window.addEventListener("pointerup", () => {
  if (!isDragging) return;
  isDragging = false;
  safeSet(STORAGE_KEY_SPLIT, parseFloat(theoryPaneEl.style.width));
  resizerV.classList.remove("dragging");
  document.body.style.cursor = "";
  document.body.style.userSelect = "";
});

// ==================== VIEW MODE ====================
function currentMode() {
  if (!MOBILE_QUERY.matches) return preferredMode;
  return compactMode;
}

function applyViewMode(mode) {
  if (MOBILE_QUERY.matches && mode === "split") mode = "theory"; // no room for two panes
  workspaceEl.className = `workspace mode-${mode}`;
  document.querySelectorAll(".seg-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.mode === mode);
  });
}

// User-initiated. The desktop choice is remembered; the small-screen one is not,
// so flipping to "code" on a phone doesn't overwrite your split-view preference.
function setViewMode(mode) {
  if (MOBILE_QUERY.matches) {
    compactMode = mode;
  } else {
    preferredMode = mode;
    safeSet(STORAGE_KEY_VIEW_MODE, mode);
  }
  applyViewMode(mode);
}

document.querySelectorAll(".seg-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    if (!btn.disabled) setViewMode(btn.dataset.mode);
  });
});

// ==================== SIDEBAR ====================
function closeSidebar() {
  sidebarEl.classList.add("collapsed");
  document.body.classList.remove("sidebar-open");
}

document.getElementById("toggle-sidebar-btn").addEventListener("click", () => {
  const collapsed = sidebarEl.classList.toggle("collapsed");
  document.body.classList.toggle("sidebar-open", !collapsed && MOBILE_QUERY.matches);
});
sidebarBackdropEl.addEventListener("click", closeSidebar);

function syncSidebarForViewport() {
  if (MOBILE_QUERY.matches) closeSidebar();
  else {
    sidebarEl.classList.remove("collapsed");
    document.body.classList.remove("sidebar-open");
  }
}

MOBILE_QUERY.addEventListener("change", () => {
  syncSidebarForViewport();
  // rotating a tablet / resizing across the breakpoint: re-pick the layout
  if (currentModule?.files?.length) {
    if (MOBILE_QUERY.matches) compactMode = workspaceEl.classList.contains("mode-code") ? "code" : "theory";
    applyViewMode(currentMode());
  }
});

// ==================== VIEWER CONTROLS ====================
copyCodeBtn.addEventListener("click", () => {
  const fileObj = currentModule?.files?.[activeFileIndex];
  if (fileObj) copyText(fileObj.content, copyCodeBtn, "Copy");
});
downloadCodeBtn.addEventListener("click", downloadActiveFile);

// ==================== PAGER ====================
function navigateAdjacent(offset) {
  if (!currentModule) return;
  const idx = flatModules.findIndex((m) => m.id === currentModule.id);
  if (idx !== -1 && flatModules[idx + offset]) selectModule(flatModules[idx + offset].id);
}

prevBtn.addEventListener("click", () => navigateAdjacent(-1));
nextBtn.addEventListener("click", () => navigateAdjacent(1));

// ==================== SEARCH ====================
let searchTimer = null;
let searchSeq = 0;
let searchIndexPromise = null;

// Loaded once, on the first search, so normal page loads stay light.
function loadSearchIndex() {
  if (!searchIndexPromise) {
    searchIndexPromise = fetch(DATA_URL.searchIndex)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .catch((err) => {
        searchIndexPromise = null; // allow a retry on the next keystroke
        throw err;
      });
  }
  return searchIndexPromise;
}

function snippetAround(text, idx, qLen, before, after) {
  const start = Math.max(0, idx - before);
  const end = Math.min(text.length, idx + qLen + after);
  return text.slice(start, end).replace(/\s*\n\s*/g, " ").trim();
}

// Same ranking as before: lesson title, then theory text, then source files.
function searchIndex(index, query) {
  const q = query.toLowerCase();
  const results = [];
  for (const mod of index) {
    if (mod.moduleTitle.toLowerCase().includes(q) || mod.moduleId.toLowerCase().includes(q)) {
      results.push({ moduleId: mod.moduleId, moduleTitle: mod.moduleTitle, fileName: "README.md", matchType: "Bài học", snippet: mod.moduleTitle });
    } else {
      const idx = mod.readme.toLowerCase().indexOf(q);
      if (idx !== -1) {
        results.push({
          moduleId: mod.moduleId, moduleTitle: mod.moduleTitle, fileName: "README.md", matchType: "Lý thuyết",
          snippet: `...${snippetAround(mod.readme, idx, q.length, 40, 60)}...`,
        });
      }
    }
    for (const f of mod.files) {
      const idx = f.content.toLowerCase().indexOf(q);
      if (idx === -1 && !f.name.toLowerCase().includes(q)) continue;
      results.push({
        moduleId: mod.moduleId, moduleTitle: mod.moduleTitle, fileName: f.name, matchType: "Mã nguồn",
        snippet: idx === -1 ? f.name : snippetAround(f.content, idx, q.length, 35, 55),
      });
      if (results.length >= SEARCH_LIMIT) return results;
    }
  }
  return results;
}

function resetSearch() {
  searchInputEl.value = "";
  searchClearBtn.classList.add("hidden");
  searchKbdEl.classList.remove("hidden");
  searchResultsPanelEl.classList.add("hidden");
  curriculumNavEl.classList.remove("hidden");
}

function highlightMatch(text, q) {
  const safe = escapeHtml(text);
  const safeQ = escapeHtml(q).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return safeQ ? safe.replace(new RegExp(safeQ, "gi"), (m) => `<mark>${m}</mark>`) : safe;
}

searchInputEl.addEventListener("input", () => {
  const q = searchInputEl.value.trim();
  searchClearBtn.classList.toggle("hidden", q.length === 0);
  searchKbdEl.classList.toggle("hidden", q.length > 0);
  clearTimeout(searchTimer);
  if (!q) {
    searchResultsPanelEl.classList.add("hidden");
    curriculumNavEl.classList.remove("hidden");
    return;
  }

  searchTimer = setTimeout(async () => {
    const seq = ++searchSeq;
    curriculumNavEl.classList.add("hidden");
    searchResultsPanelEl.classList.remove("hidden");
    if (!searchIndexPromise) searchResultsPanelEl.innerHTML = `<div class="search-empty">Đang tải chỉ mục tìm kiếm…</div>`;

    const data = { results: [] };
    try {
      data.results = searchIndex(await loadSearchIndex(), q);
    } catch (err) {
      if (seq !== searchSeq) return;
      searchResultsPanelEl.innerHTML = `<div class="search-empty">Không tải được chỉ mục tìm kiếm (${escapeHtml(err.message)})</div>`;
      return;
    }
    if (seq !== searchSeq || searchInputEl.value.trim() !== q) return;

    if (data.results.length === 0) {
      searchResultsPanelEl.innerHTML = `<div class="search-empty">Không tìm thấy kết quả cho “${escapeHtml(q)}”</div>`;
      return;
    }

    searchResultsPanelEl.innerHTML = `<div class="search-count">${data.results.length}${
      data.results.length >= SEARCH_LIMIT ? "+" : ""
    } kết quả</div>`;
    data.results.forEach((item) => {
      const hit = document.createElement("button");
      hit.className = "search-hit";
      hit.innerHTML = `
        <div class="search-hit-title">${escapeHtml(cleanTitle(item.moduleTitle))}</div>
        <div class="search-hit-sub"><span class="hit-tag">${escapeHtml(item.matchType)}</span>${escapeHtml(
        item.fileName
      )}</div>
        <div class="search-hit-code">${highlightMatch(item.snippet, q)}</div>
      `;
      hit.addEventListener("click", () => {
        selectModule(item.moduleId, item.fileName !== "README.md" ? item.fileName : null);
        if (MOBILE_QUERY.matches) closeSidebar();
      });
      searchResultsPanelEl.appendChild(hit);
    });
  }, 180);
});

searchInputEl.addEventListener("keydown", (e) => {
  if (e.key === "Escape") {
    resetSearch();
    searchInputEl.blur();
  } else if (e.key === "Enter") {
    searchResultsPanelEl.querySelector(".search-hit")?.click();
  }
});

searchClearBtn.addEventListener("click", () => {
  resetSearch();
  searchInputEl.focus();
});

// ==================== GLOBAL SHORTCUTS ====================
window.addEventListener("keydown", (e) => {
  const typing = ["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName);
  if (e.key === "Escape" && document.body.classList.contains("sidebar-open")) {
    closeSidebar();
  } else if (e.key === "/" && !typing) {
    e.preventDefault();
    if (sidebarEl.classList.contains("collapsed")) document.getElementById("toggle-sidebar-btn").click();
    searchInputEl.focus();
    searchInputEl.select();
  } else if (e.altKey && e.key === "ArrowLeft" && !typing) {
    e.preventDefault();
    navigateAdjacent(-1);
  } else if (e.altKey && e.key === "ArrowRight" && !typing) {
    e.preventDefault();
    navigateAdjacent(1);
  }
});

window.addEventListener("hashchange", () => {
  const hashId = decodeURIComponent(window.location.hash.replace("#", ""));
  if (hashId && (!currentModule || currentModule.id !== hashId)) selectModule(hashId);
});

initTheme();
syncSidebarForViewport();
loadCurriculum();
